const menu=document.querySelector('.menu-toggle');
if(menu)menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('.nav').classList.toggle('open',open);menu.textContent=open?'Close':'Menu';});
const layers=[
 ['01','Start with a useful question.','An agent proposes a claim or a query. Preserve the evidence, source, and scope before asking a symbolic system to justify it.','/articles/trust-boundary/','Understand the boundary'],
 ['02','Search for an explanation.','lean-elpi brings λProlog to Lean: higher-order terms, scoped assumptions, and proof search. Certification is an explicit layer, not a property of every search result.','https://volland.github.io/lean-elpi/','Explore lean-elpi'],
 ['03','Give the graph a meaning.','LeanRDF formalizes RDF and RDFS, then extends the semantic stack with SPARQL, OWL RL/EL, and SHACL. Each layer has its own contract.','/articles/semantic-stack/','Explore the semantic stack'],
 ['04','Choose how knowledge lives.','typedb-lean and ladybug-lean are alternative typed storage paths. They connect database operations to Lean types; an application must explicitly connect stored data to proof obligations.','/projects/#storage','Compare graph adapters'],
 ['05','Check against the foundation.','Lean’s dependent type theory lets propositions be types and proofs be terms. The kernel checks proof terms against their claimed types, relative to the definitions and axioms used.','/articles/dependent-types/','Learn dependent types']
];
document.querySelectorAll('.stack-layer').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.stack-layer').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});btn.classList.add('active');btn.setAttribute('aria-pressed','true');const d=layers[Number(btn.dataset.layer)],p=document.querySelector('.stack-detail');p.querySelector('.number').textContent=d[0];p.querySelector('h3').textContent=d[1];p.querySelector('p').textContent=d[2];p.querySelector('a').href=d[3];p.querySelector('a').textContent=d[4]+' ↗';}));
const filters=document.querySelectorAll('.filter-btn');let active='all';const search=document.querySelector('.resource-search');
function filterItems(){let shown=0;document.querySelectorAll('[data-category]').forEach(card=>{const ok=(active==='all'||card.dataset.category.split(' ').includes(active))&&(!search||card.textContent.toLowerCase().includes(search.value.toLowerCase()));card.hidden=!ok;if(ok)shown++;});const empty=document.querySelector('.empty-state');if(empty)empty.hidden=shown!==0;const count=document.querySelector('.result-count');if(count)count.textContent=shown+' resources';}
filters.forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter;filters.forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});filterItems();}));if(search)search.addEventListener('input',filterItems);
